#include <stddef.h>
#define PARAM_MAGIC 0xA5u

typedef struct {
    unsigned char magic;
    unsigned char seq;
    unsigned char data[8];
} ParamSlot;

int param_select_slot(const ParamSlot *slots, int count)
{
    if (slots == NULL || count <= 0) {
        return -2;
    }

    int best = -1;

    for (int i = 0; i < count; i++) {
        if (slots[i].magic != PARAM_MAGIC) {
            continue;  /* 未写入的槽不参与比较 */
        }

        if (best < 0) {
            best = i;
            continue;
        }

        unsigned char delta = (unsigned char)(slots[i].seq - slots[best].seq);

        if (delta >= 1u && delta <= 127u) {
            best = i;  /* 候选槽更新 */
        }
        /* delta == 0（同一序号）或 delta >= 128（候选更旧）：保留当前最优槽 */
    }

    return best;
}
